def measure(capacities, steps, target):
    """Simulate jug steps and return True if `target` liters end up in some jug."""
    state = {j: 0 for j in capacities}

    for step in steps:
        parts = step.split()
        cmd = parts[0]

        if cmd == "fill":
            j = parts[1]
            state[j] = capacities[j]

        elif cmd == "empty":
            j = parts[1]
            state[j] = 0

        elif cmd == "pour":
            a, b = parts[1], parts[2]
            amount = min(state[a], capacities[b] - state[b])
            state[a] -= amount
            state[b] += amount

        else:
            raise ValueError(f"unknown step: {step!r}")

        if any(v < 0 or v > capacities[j] for j, v in state.items()):
            return False  # invalid state

    return target in state.values()


# --- demo: 8L & 5L jugs, measure 6L ---
caps = {"8": 8, "5": 5}
steps = [
    "fill 8",
    "pour 8 5",   # 8:3, 5:5
    "empty 5",    # 8:3, 5:0
    "pour 8 5",   # 8:0, 5:3
    "fill 8",     # 8:8, 5:3
    "pour 8 5",   # 8:6, 5:5  <- 6 liters
]
print(measure(caps, steps, 6))  # True
